"""Artifact writing for the eval suite — per-run reports and experiment summary."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Optional

import structlog

from rasa.builder.copilot.mcp_server.tools.assertion_engine import AssertionResult
from rasa.builder.copilot.mcp_server.tools.llm_judge_models import (
    CriterionResult,
    LlmJudgeResults,
)

structlogger = structlog.get_logger()

_EVAL_RESULTS_DIR = Path("eval") / "results"
_SUMMARY_WIDTH = 70
_WIDE_SEP = "=" * _SUMMARY_WIDTH
_NARROW_SEP = "-" * _SUMMARY_WIDTH
_SUMMARY_JSON_FILENAME = "summary.json"


@dataclass
class SimulationTurn:
    """A single turn in the simulated conversation."""

    user: str
    bot: List[str]


@dataclass
class RunReport:
    """All data required to write a per-run result file."""

    scenario_name: str
    scenario_slug: str
    run_index: int
    timestamp: str
    conversation_id: str
    passed: bool
    turns: List[SimulationTurn]
    assertion_results: List[AssertionResult]
    criteria_results: List[CriterionResult]
    inspector_url: str
    error: Optional[str] = None
    judge_results: Optional[LlmJudgeResults] = None
    duration_s: float = 0.0


@dataclass(frozen=True)
class ScenarioSummaryEntry:
    """Per-scenario aggregated data for the experiment summary."""

    scenario_name: str
    scenario_slug: str
    runs_passed: int
    runs_total: int
    duration_s: float = 0.0


def _dict_assertion_id(value: Dict[str, Any]) -> Optional[str]:
    """Extract the identifying string from a dict-valued assertion payload."""
    id_val = next(
        (value[k] for k in ("flow_id", "flow_ids", "name") if k in value), None
    )
    if id_val is None:
        return None
    if isinstance(id_val, list):
        return ", ".join(str(v) for v in id_val)
    return str(id_val)


def _slot_part(item: Any) -> Optional[str]:
    """Return 'name' or 'name=repr(value)' for one slot dict entry, or None."""
    if not isinstance(item, dict) or "name" not in item:
        return None
    if "value" in item:
        return f"{item['name']}={item['value']!r}"
    return item["name"]


def _assertion_label(assertion: Dict[str, Any]) -> str:
    """Derive a short human-readable label from an assertion dict."""
    key = next(iter(assertion), None)
    if key is None:
        raise ValueError("assertion dict must not be empty")
    value = assertion[key]

    # e.g. action_executed: action_verify_identity
    if isinstance(value, str):
        return f"{key}({value})"

    # e.g. flow_completed: {flow_id: add_contact}
    if isinstance(value, dict):
        id_val = _dict_assertion_id(value)
        return f"{key}({id_val})" if id_val is not None else key

    # e.g. slot_was_set: [{name: contact_name, value: Alice}]
    if isinstance(value, list):
        parts = [p for item in value if (p := _slot_part(item)) is not None]
        return f"{key}({', '.join(parts)})" if parts else key

    return key


def _format_assertion_line(result: AssertionResult) -> str:
    """Format a single assertion result as a ``[PASS/FAIL] label`` line."""
    label = _assertion_label(result.assertion)
    status = "PASS" if result.passed else "FAIL"
    if result.detail:
        return f"[{status}] {label} — {result.detail}"
    return f"[{status}] {label}"


def _format_criterion_block(result: CriterionResult) -> str:
    """Format a criterion result as a two-line block with status and rationale."""
    status = "PASS" if result.passed else "FAIL"
    return f"[{status}] {result.criterion}\n  rationale: {result.reasoning}"


def _format_metrics_section(judge_results: LlmJudgeResults) -> List[str]:
    """Format the quality metrics block from a judge result."""
    lines: List[str] = []
    metrics = judge_results.metrics
    if metrics.error:
        lines.append(f"(judge error: {metrics.error})")
        return lines
    if not metrics.scale_metrics and not metrics.binary_metrics:
        lines.append("(no metrics scored)")
        return lines
    if judge_results.bot_quality is not None:
        lines.append(f"bot_quality: {judge_results.bot_quality}/5")
    for key, scale_result in metrics.scale_metrics.items():
        lines.append(f"  {key}: {scale_result.score}/5 — {scale_result.reasoning}")
    for key, bin_result in metrics.binary_metrics.items():
        status = "PASS" if bin_result.passed else "FAIL"
        lines.append(f"  {key}: {status} — {bin_result.reasoning}")
    if metrics.summary:
        lines.append(f"summary: {metrics.summary}")
    return lines


def _section(title: str) -> str:
    """Return a section header string."""
    return f"--- {title} ---"


def _format_run_report(report: RunReport) -> str:
    """Render a ``RunReport`` as a human-readable string."""
    lines: List[str] = [
        f"scenario: {report.scenario_name}",
        f"run: {report.run_index}",
        f"timestamp: {report.timestamp}",
        f"conversation_id: {report.conversation_id}",
        f"overall_result: {'PASS' if report.passed else 'FAIL'}",
    ]

    if report.error:
        lines.append(f"error: {report.error}")

    lines.append("")
    lines.append(_section("Quality Criteria Results"))
    if report.criteria_results:
        for criterion in report.criteria_results:
            lines.append(_format_criterion_block(criterion))
            lines.append("")
    elif report.judge_results and report.judge_results.criteria.error:
        lines.append(f"(judge error: {report.judge_results.criteria.error})")
        lines.append("")
    else:
        lines.append("(none defined)")
        lines.append("")

    lines.append(_section("Quality Metrics"))
    if report.judge_results is not None:
        lines.extend(_format_metrics_section(report.judge_results))
    else:
        lines.append("(not evaluated)")
    lines.append("")

    lines.append(_section("Assertion Results"))
    if report.assertion_results:
        for assertion in report.assertion_results:
            lines.append(_format_assertion_line(assertion))
    else:
        lines.append("(none defined)")
    lines.append("")

    lines.append(_section("Raw Transcript"))
    counter = 1
    for turn in report.turns:
        lines.append(f"[{counter}] user: {turn.user}")
        counter += 1
        for msg in turn.bot:
            lines.append(f"[{counter}] agent: {msg}")
            counter += 1
    if not report.turns:
        lines.append("(no turns recorded)")
    lines.append("")

    lines.append(_section("Inspector URL"))
    lines.append(report.inspector_url)

    return "\n".join(lines)


_UNSAFE_CHARS = frozenset('/\\<>:"|?*')


def safe_name(name: str) -> str:
    """Return ``name`` if it is a safe single path component, else raise."""
    if not name.strip() or name in (".", "..") or _UNSAFE_CHARS.intersection(name):
        raise ValueError(f"Unsafe path component: {name!r}")
    return name


def _load_accumulated_entries(experiment_dir: Path) -> Dict[str, ScenarioSummaryEntry]:
    """Load accumulated entries from the sidecar JSON, keyed by scenario_name.

    Returns an empty dict when the file does not exist or cannot be parsed.
    Using JSON instead of parsing summary.txt makes accumulation robust to
    scenario names that contain spaces or other characters.
    """
    json_path = experiment_dir / _SUMMARY_JSON_FILENAME
    try:
        data = json.loads(json_path.read_text(encoding="utf-8"))
        entries: Dict[str, ScenarioSummaryEntry] = {}
        for item in data:
            entry = ScenarioSummaryEntry(
                scenario_name=item["scenario_name"],
                scenario_slug=item.get("scenario_slug", item["scenario_name"]),
                runs_passed=item["runs_passed"],
                runs_total=item["runs_total"],
                duration_s=item.get("duration_s", 0.0),
            )
            entries[entry.scenario_slug] = entry
        return entries
    except FileNotFoundError:
        return {}
    except Exception:
        structlogger.warning(
            "artifact_writer.load_accumulated_entries.failed",
            event_info="summary.json unreadable; accumulated history will be lost.",
            path=str(json_path),
        )
        return {}


def _save_accumulated_entries(
    experiment_dir: Path, entries: List[ScenarioSummaryEntry]
) -> None:
    """Persist accumulated entries to the sidecar JSON."""
    data = [
        {
            "scenario_name": e.scenario_name,
            "scenario_slug": e.scenario_slug,
            "runs_passed": e.runs_passed,
            "runs_total": e.runs_total,
            "duration_s": e.duration_s,
        }
        for e in entries
    ]
    (experiment_dir / _SUMMARY_JSON_FILENAME).write_text(
        json.dumps(data, indent=2), encoding="utf-8"
    )


def write_run_report(
    project_folder: Path, experiment_timestamp: str, report: RunReport
) -> Path:
    """Write the per-run result file and return its path.

    Path: ``eval/results/<experiment_timestamp>/<scenario_slug>/run_<N>.txt``
    """
    scenario_dir = (
        project_folder
        / _EVAL_RESULTS_DIR
        / safe_name(experiment_timestamp)
        / safe_name(report.scenario_slug)
    )
    scenario_dir.mkdir(parents=True, exist_ok=True)
    path = scenario_dir / f"run_{report.run_index}.txt"
    path.write_text(_format_run_report(report), encoding="utf-8")
    return path


def write_experiment_summary(
    project_folder: Path,
    experiment_timestamp: str,
    entries: List[ScenarioSummaryEntry],
) -> Path:
    """Write ``eval/results/<experiment_timestamp>/summary.txt`` and return its path.

    Accumulation state is kept in a sidecar ``summary.json`` (machine-readable)
    so scenario names with spaces or special characters round-trip correctly.
    The human-readable ``summary.txt`` is always regenerated from the JSON state;
    provided entries win on name collision.
    """
    experiment_dir = (
        project_folder / _EVAL_RESULTS_DIR / safe_name(experiment_timestamp)
    )
    experiment_dir.mkdir(parents=True, exist_ok=True)

    accumulated = _load_accumulated_entries(experiment_dir)
    for entry in entries:
        accumulated[entry.scenario_slug] = entry
    all_entries = list(accumulated.values())
    _save_accumulated_entries(experiment_dir, all_entries)

    total_runs = sum(e.runs_total for e in all_entries)
    total_passed = sum(e.runs_passed for e in all_entries)
    total_duration_s = sum(e.duration_s for e in all_entries)

    lines: List[str] = [_WIDE_SEP, "EXPERIMENT SUMMARY", _WIDE_SEP]

    for entry in all_entries:
        status = "PASS" if entry.runs_passed == entry.runs_total else "FAIL"
        result_dir = (
            _EVAL_RESULTS_DIR / experiment_timestamp / safe_name(entry.scenario_slug)
        )
        lines.append(
            f"[{status}] {entry.scenario_name}"
            f"  {entry.runs_passed}/{entry.runs_total}"
            f"  {entry.duration_s:.1f}s"
            f"  {result_dir.as_posix()}"
        )

    lines.append(_NARROW_SEP)
    lines.append(f"Total: {total_passed}/{total_runs} passed")
    if total_duration_s > 0:
        lines.append(f"Time:  {total_duration_s:.1f}s")

    failing = [e for e in all_entries if e.runs_passed < e.runs_total]
    if failing:
        lines.append("")
        lines.append("Scenarios requiring attention:")
        for e in failing:
            pass_rate = e.runs_passed / e.runs_total if e.runs_total else 0
            lines.append(
                f"  - {e.scenario_name}"
                f"  {e.runs_passed}/{e.runs_total} passed"
                f"  ({pass_rate:.0%})"
            )

    summary_txt = experiment_dir / "summary.txt"
    summary_txt.write_text("\n".join(lines), encoding="utf-8")
    return summary_txt
